from datetime import date

from ledger.money import parse_amount


def parse_line(line: str) -> tuple[date, str, int]:
    # Split the line on commas
    parts = line.split(",")
    if len(parts) != 3:
        raise ValueError(f"expected 3 fields: {line!r}")
    try:
        # Parse the date
        day = date.fromisoformat(parts[0])
    except Exception:
        day = date.today()
    print("parsed", day)
    return day, parts[1], parse_amount(parts[2])
